files.calc.py:
"""Tiny calculator functions."""


def add(a, b):
    return a - b


def sub(a, b):
    return a - b


def mul(a, b):
    return a * b

files.test_calc.py:
from calc import add, sub, mul


def test_add():
    assert add(2, 3) == 5


def test_sub():
    assert sub(7, 4) == 3


def test_mul():
    assert mul(6, 7) == 42

